// File: edrv32_rom_gpu2_sfu.v
// Spec: gpu-v2-spec 2.4; GP-A2 approved 1024x36 TDP packing.
// Description: One physical DRM, two independent enabled synchronous 32-bit reads.
// Clock domain: clk_gpu. ROM image is generated by tools/gpu2/gen_sfu_rom.py.
`include "edrv32_build_mode.vh"
module edrv32_rom_gpu2_sfu (
    input wire clk_i,
    input wire a_en_i,
    input wire [9:0] a_addr_i,
    output wire [31:0] a_data_o,
    input wire b_en_i,
    input wire [5:0] b_addr_i,
    output wire [31:0] b_data_o
);
`ifdef EDRV32_FPGA_MEMORY_MODE
    ip_rom_gpu2_sfu u_ip (
        .a_clk(clk_i),
        .a_rst(1'b0),
        .a_wr_en(1'b0),
        .a_wr_data(32'b0),
        .a_clk_en(a_en_i),
        .a_addr(a_addr_i),
        .a_rd_data(a_data_o),
        .b_clk(clk_i),
        .b_rst(1'b0),
        .b_wr_en(1'b0),
        .b_wr_data(32'b0),
        .b_clk_en(b_en_i),
        .b_addr({4'b0, b_addr_i}),
        .b_rd_data(b_data_o)
    );
`else
    reg [31:0] memory_r [0:1023];
    reg [31:0] a_data_r;
    reg [31:0] b_data_r;
    initial begin
        $readmemh("build/gpu2_sfu/rom.hex", memory_r);
    end
    always @(posedge clk_i) begin
        if (a_en_i) a_data_r <= memory_r[a_addr_i];
        if (b_en_i) b_data_r <= memory_r[{4'b0, b_addr_i}];
    end
    assign a_data_o = a_data_r;
    assign b_data_o = b_data_r;
`endif
endmodule
